import hashlib
import hmac
import json
import os
import sqlite3
import time
import re
from flask import Flask, request, abort, jsonify, g
from functools import wraps

app = Flask(__name__)

SECRET_KEY = os.environ['APP_SECRET_KEY']
DB_PATH = os.environ.get('DB_PATH', '/var/lib/app/data.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def create_token(user_id, role, expires_at):
    """Create a signed token: base64(payload).signature"""
    payload = json.dumps({'uid': user_id, 'role': role, 'exp': expires_at})
    import base64
    encoded_payload = base64.urlsafe_b64encode(payload.encode()).decode().rstrip('=')
    sig = hmac.new(SECRET_KEY.encode(), encoded_payload.encode(), hashlib.sha256).hexdigest()
    return f"{encoded_payload}.{sig}"

def verify_token(token):
    """Verify token signature and extract claims."""
    parts = token.split('.')
    if len(parts) != 2:
        return None
    encoded_payload, provided_sig = parts
    expected_sig = hmac.new(SECRET_KEY.encode(), encoded_payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(provided_sig, expected_sig):
        return None
    import base64
    # Add padding back
    padded = encoded_payload + '=' * (4 - len(encoded_payload) % 4)
    try:
        payload = json.loads(base64.urlsafe_b64decode(padded))
    except (json.JSONDecodeError, Exception):
        return None
    if payload.get('exp', 0) < time.time():
        return None
    return payload

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)
        token = auth_header[7:]
        claims = verify_token(token)
        if claims is None:
            abort(401)
        g.claims = claims
        g.user_id = claims['uid']
        g.role = claims.get('role', 'user')
        return f(*args, **kwargs)
    return decorated

def check_document_access(doc_id, user_id):
    """Verify the authenticated user owns the document or doc is shared.
    Returns the document row if access is granted, None otherwise."""
    db = get_db()
    doc = db.execute(
        'SELECT * FROM documents WHERE id = ?', (doc_id,)
    ).fetchone()
    if doc is None:
        return None
    # Check ownership: compare as strings for consistent type handling
    # across different DB backends (some return int, some str)
    if str(doc['owner_id']) == str(user_id):
        return doc
    # Check if document is shared with this user
    share = db.execute(
        'SELECT * FROM document_shares WHERE doc_id = ? AND shared_with = ?',
        (doc_id, int(user_id))
    ).fetchone()
    if share is not None:
        return doc
    return None

def check_admin_action(action, resource_owner_id):
    """Validate that the current user can perform admin actions.
    Admin can act on any resource. Managers can act on their team's resources."""
    if g.role == 'admin':
        return True
    if g.role == 'manager':
        db = get_db()
        # Managers can manage users in their team
        team = db.execute(
            'SELECT * FROM team_members WHERE manager_id = ? AND member_id = ?',
            (int(g.user_id), int(resource_owner_id))
        ).fetchone()
        return team is not None
    return False

@app.route('/api/documents', methods=['GET'])
@require_auth
def list_documents():
    """List documents owned by or shared with the authenticated user."""
    db = get_db()
    docs = db.execute(
        '''SELECT d.* FROM documents d 
           WHERE d.owner_id = ? 
           UNION 
           SELECT d.* FROM documents d 
           JOIN document_shares ds ON d.id = ds.doc_id 
           WHERE ds.shared_with = ?''',
        (int(g.user_id), int(g.user_id))
    ).fetchall()
    return jsonify([dict(d) for d in docs])

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    """Get a specific document if the user has access."""
    doc = check_document_access(doc_id, g.user_id)
    if doc is None:
        abort(404)
    return jsonify(dict(doc))

@app.route('/api/documents/<int:doc_id>', methods=['PUT'])
@require_auth
def update_document(doc_id):
    """Update a document. Only the owner can update."""
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if doc is None:
        abort(404)
    # Only owner can edit - strict ownership check
    if doc['owner_id'] != int(g.user_id):
        abort(403)
    data = request.get_json()
    if not data or 'content' not in data:
        abort(400)
    # Sanitize content - no script tags
    content = data['content']
    if re.search(r'<script', content, re.IGNORECASE):
        abort(400)
    db.execute(
        'UPDATE documents SET content = ?, updated_at = ? WHERE id = ?',
        (content, int(time.time()), doc_id)
    )
    db.commit()
    return jsonify({'status': 'updated'})

@app.route('/api/documents/<int:doc_id>/share', methods=['POST'])
@require_auth
def share_document(doc_id):
    """Share a document with another user. Only owner can share."""
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if doc is None:
        abort(404)
    if doc['owner_id'] != int(g.user_id):
        abort(403)
    data = request.get_json()
    if not data or 'user_id' not in data:
        abort(400)
    target_user = int(data['user_id'])
    # Verify target user exists
    user = db.execute('SELECT id FROM users WHERE id = ?', (target_user,)).fetchone()
    if user is None:
        abort(400)
    db.execute(
        'INSERT OR IGNORE INTO document_shares (doc_id, shared_with, shared_at) VALUES (?, ?, ?)',
        (doc_id, target_user, int(time.time()))
    )
    db.commit()
    return jsonify({'status': 'shared'})

@app.route('/api/admin/documents/<int:doc_id>/transfer', methods=['POST'])
@require_auth
def transfer_document(doc_id):
    """Transfer document ownership. Requires admin or manager role."""
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if doc is None:
        abort(404)
    if not check_admin_action('transfer', doc['owner_id']):
        abort(403)
    data = request.get_json()
    if not data or 'new_owner_id' not in data:
        abort(400)
    new_owner = int(data['new_owner_id'])
    user = db.execute('SELECT id FROM users WHERE id = ?', (new_owner,)).fetchone()
    if user is None:
        abort(400)
    db.execute(
        'UPDATE documents SET owner_id = ?, updated_at = ? WHERE id = ?',
        (new_owner, int(time.time()), doc_id)
    )
    db.commit()
    return jsonify({'status': 'transferred'})

@app.route('/api/admin/users/<int:target_id>/documents', methods=['GET'])
@require_auth
def admin_list_user_documents(target_id):
    """Admin endpoint to list any user's documents."""
    if not check_admin_action('view', target_id):
        abort(403)
    db = get_db()
    docs = db.execute(
        'SELECT * FROM documents WHERE owner_id = ?', (target_id,)
    ).fetchall()
    return jsonify([dict(d) for d in docs])

@app.route('/api/documents/search', methods=['GET'])
@require_auth
def search_documents():
    """Search documents the user has access to."""
    query = request.args.get('q', '')
    if not query or len(query) < 2:
        abort(400)
    db = get_db()
    # Search only in user's own documents and shared documents
    docs = db.execute(
        '''SELECT d.* FROM documents d 
           WHERE (d.owner_id = ? OR d.id IN (
               SELECT doc_id FROM document_shares WHERE shared_with = ?
           )) AND d.content LIKE ?''',
        (int(g.user_id), int(g.user_id), f'%{query}%')
    ).fetchall()
    return jsonify([dict(d) for d in docs])

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
